 const videos=[...document.querySelectorAll('.network-feed video')];observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const entry of entries)if(!entry.isIntersecting)entry.target.pause()},{threshold:.55});videos.forEach(v=>{const mediaError=()=>{if(!v.parentElement.querySelector('.media-error'))v.insertAdjacentHTML('afterend','<p class="media-error" role="status">Video non disponibile o formato non supportato da questo browser.</p>')};v.addEventListener('error',mediaError,{signal});if(v.error)mediaError();observer.observe(v);v.addEventListener('play',()=>videos.forEach(other=>{if(other!==v)other.pause()}),{signal})});
