 return {page,bind,expire(){if(data){const old=data.posts.length;data.posts=data.posts.filter(p=>(!p.expires||p.expires>Date.now())&&(!recent||p.created>=Date.now()-7200000));if(old!==data.posts.length&&isRoute())ctx.render()}},refreshWeather(){if(isRoute()&&currentKey()!==key){key='';ctx.render();return}pulse.refresh();const empty=$('#network-empty-weather');if(empty)empty.innerHTML=emptyWeather();const forecast=$('#community-forecast');if(forecast)forecast.innerHTML=forecastHTML();const same=$('[data-net-same]');if(same){same.disabled=false;same.textContent=sameSkyTopic(ctx.get().weather)?'Stesso cielo · '+sameSkyTopic(ctx.get().weather):'Esplora tutti i cieli';}document.querySelectorAll('[data-net-question]').forEach(b=>b.onclick=()=>ctx.askQuestion())},showCity(value){mode='local';city=value;query='';topic='';recent=false;key=''},disposeView(){if(skyRoute&&skyRoute!==ctx.get().route){stopSky();skyRoute='';if($('#sky-camera'))$('#dialog')?.close()}events?.abort();observer?.disconnect();document.querySelectorAll('.network-feed video').forEach(v=>v.pause())},invalidate(){key=''}};
